# Activity customizations (Docker/CUSTOMIZATIONS.md "Activity").
if want activity; then
  check activity.health '^healthy$' "$(docker inspect -f '{{.State.Health.Status}}' activity 2>&1)"
  check activity.hardening '^65060:65060 ro=true caps=\[ALL\] nnp mem=33554432$' "$(docker inspect -f '{{.Config.User}} ro={{.HostConfig.ReadonlyRootfs}} caps={{.HostConfig.CapDrop}} {{range .HostConfig.SecurityOpt}}{{if eq . "no-new-privileges:true"}}nnp{{end}}{{end}} mem={{.HostConfig.Memory}}' activity 2>&1)"
  # never served without a login: 302 to the SSO (Authentik application Activity)
  check activity.page-sso '^302 https://sso\.holy-grail\.ch/application/o/authorize/' "$(curl -sk -m 10 -o /dev/null -w '%{http_code} %{redirect_url}' --resolve activity.holy-grail.ch:443:192.168.1.2 https://activity.holy-grail.ch/ | cut -c1-60)"
  # idle = no poll: with no viewer, the last poll time must not move for 31 s (skipped while someone views); then one /api/state read makes it a viewer
  check activity.viewer-gated '^(idle-no-poll|viewed) then-active$' "$(m() { docker exec prometheus wget -qO- -T 5 http://activity:8080/metrics 2>&1 | grep -E '^activity_(viewer_active|last_poll_timestamp_seconds) '; }; a=$(m); if grep -q '^activity_viewer_active 0$' <<<"$a"; then sleep 31; [[ $(m | grep last_poll) == $(grep last_poll <<<"$a") ]] && b=idle-no-poll || b=idle-polled; else b=viewed; fi; docker exec traefik wget -qO /dev/null -T 10 http://activity:8080/api/state >/dev/null 2>&1; m | grep -q '^activity_viewer_active 1$' && echo "$b then-active" || echo "$b then-inactive")"
  check activity.api '^"beefy":"(up|asleep|waking|broken|unknown)"$' "$(docker exec traefik wget -qO- -T 5 http://activity:8080/api/state 2>&1 | grep -o '"beefy":"[a-z]*"')"
  # only Traefik's pinned address (and Prometheus) may connect: another container on traefik_proxy is dropped at accept, without an HTTP answer
  check activity.traefik-only '^dropped,dropped,dropped$' "$(st() { local o; o=$(docker exec server-specs wget -qO /dev/null -T 5 "http://activity:8080$1" 2>&1); case $o in *'HTTP/1.1 '*) grep -o 'HTTP/1.1 [0-9]*' <<<"$o" | head -1 | cut -d' ' -f2 ;; '') echo 200 ;; *) echo dropped ;; esac; }; echo "$(st /api/state),$(st /),$(st /health)")"
  # Traefik's internal routes (../Traefik/traefik/dynamic/activity-internal.yml): the Waker answers through it, qBittorrent too, and nobody but activity gets in
  check activity.waker-route '^"beefy":"(up|asleep|waking|broken)"$' "$(docker exec traefik wget -qO- -T 5 http://activity:8080/api/state 2>&1 | grep -o '"beefy":"[a-z]*"')"
  check activity.qbit-route '^"audiobook_downloads":\{"downloading":[0-9]+' "$(docker exec traefik wget -qO- -T 5 http://activity:8080/api/state 2>&1 | grep -oE '"audiobook_downloads":(null|\{"downloading":[0-9]+)')"
  check activity.internal-only '^403,403,403$' "$(st() { docker exec server-specs wget -qO /dev/null -T 5 "http://traefik:8080$1" 2>&1 | grep -o 'HTTP/1.1 [0-9]*' | cut -d' ' -f2 || true; }; echo "$(st /activity/waker/status),$(st /activity/gate/seerr/night-waiting.json),$(st '/activity/qbit/api/v2/torrents/info?category=abr')")"
  # Traefik never holds an idle connection to the beefy gate and never health-checks it (activity-internal.yml)
  check activity.gate-transport '^transport=activity-gate-no-idle idle=1s header=5s healthcheck=none$' "$(f="$DIR/../../Traefik/traefik/dynamic/activity-internal.yml"; gate=$(sed -n '/^  services:/,$p' "$f" | sed -n '/^    activity-gate:$/,/^    activity-qbit:$/p'); echo "transport=$(sed -n 's/^ *serversTransport: *//p' <<<"$gate") idle=$(sed -n '/^    activity-gate-no-idle:$/,/^    [a-z]/s/^ *idleConnTimeout: *//p' "$f") header=$(sed -n '/^    activity-gate-no-idle:$/,/^    [a-z]/s/^ *responseHeaderTimeout: *//p' "$f") healthcheck=$(grep -q healthCheck <<<"$gate" && echo set || echo none)")"
  # the qBittorrent route pins every category value to abr and refuses the other torrents/info parameters (full test: Activity/tests/traefik/run.sh); no access-log lines for the three internal routes
  check activity.qbit-rule '^pinned no-access-log=3$' "$(f="$DIR/../../Traefik/traefik/dynamic/activity-internal.yml"; grep -qF '!QueryRegexp(`category`, `(?s)^(?:|[^a].*|a|a[^b].*|ab|ab[^r].*|abr.+)$`)' "$f" && grep -q '!QueryRegexp(`hashes`' "$f" && p=pinned || p=open; echo "$p no-access-log=$(grep -c '^        accessLogs: false$' "$f")")"
  # the page's CSP comes from the service (hashes of the inline script and style), and Traefik does not replace it
  check activity.csp '^hashed traefik-csp=none$' "$(h=$(docker exec traefik wget -S -qO /dev/null -T 5 http://activity:8080/ 2>&1 | grep -i 'content-security-policy'); grep -q "script-src 'sha256-" <<<"$h" && ! grep -q unsafe-inline <<<"$h" && c=hashed || c=unhashed; echo "$c traefik-csp=$(grep -q "^ *contentSecurityPolicy:" "$DIR/../../Traefik/traefik/dynamic/activity.yml" && echo set || echo none)")"
  check activity.metrics-scraped '^1$' "$(docker exec prometheus wget -qO- -T 5 'http://localhost:9090/api/v1/query?query=up%7Bjob%3D%22activity%22%7D' 2>&1 | grep -o '"value":\[[^]]*\]' | grep -o '"[01]"' | tr -d '"')"
fi
